/// Query parameters for `GET /analysis/stalker/sector` (Sector Stalker).
#[derive(Debug, Clone, Default, PartialEq)]
pub struct SectorStalkerParams {
    /// Tanggal awal periode (`YYYY-MM-DD`). Harus lebih kecil atau sama dengan `to`, dengan rentang maksimal 730 hari. (example `2024-12-01`)
    pub from: String,
    /// Tanggal akhir periode (`YYYY-MM-DD`). Harus lebih besar atau sama dengan `from`. (example `2024-12-31`)
    pub to: String,
    /// Indeks acuan. `COMPOSITE` (IHSG) menampilkan rotasi antar sektor, sedangkan `SYARIAH` (saham syariah, dibandingkan dengan indeks ISSI) atau indeks sektoral IDX-IC (`IDXENERGY`, `IDXFINANCE`, dst.) menampilkan rotasi saham anggota kategori tersebut. `ISSI` diterima sebagai alias `SYARIAH`. Wajib huruf kapital. (default `COMPOSITE`, example `COMPOSITE`)
    pub base: Option<SectorStalkerBase>,
    /// Jumlah saham maksimal yang ditampilkan. Hanya berlaku jika `base` bukan `COMPOSITE`. (min `1`, max `100`, example `10`)
    pub limit: Option<i64>,
    /// Pencarian saham berdasarkan sebagian kode atau nama, mis. `BB` atau `BANK`. Hanya berlaku jika `base` bukan `COMPOSITE`. (example `BBCA`)
    pub filter: Option<String>,
    /// Kolom yang difilter: `change` = perubahan harga (%), `value` = nilai transaksi, `volume` = volume, `foreign` = net asing, `freq` = frekuensi, `bdm` = aliran dana bandar, `ritel` = aliran dana ritel, `ratio` = rasio, `open`/`high`/`low`/`close` = harga OHLC. Filter aktif hanya jika `filter_column`, `filter_operator`, dan `filter_value` dikirim bersamaan. (example `change`)
    pub filter_column: Option<SectorStalkerFilterColumn>,
    /// Operator pembanding untuk filter. Contoh: `filter_column=change&filter_operator=>&filter_value=5` menampilkan saham yang naik lebih dari 5%. (example `>`)
    pub filter_operator: Option<SectorStalkerFilterOperator>,
    /// Nilai pembanding untuk filter. Mendukung bilangan desimal dan negatif, mis. `5` atau `-2.5`. (example `5`)
    pub filter_value: Option<f64>,
}

impl SectorStalkerParams {
    /// Creates a value with the required fields set (optional fields start as `None`).
    pub fn new(from: impl Into<String>, to: impl Into<String>) -> Self {
        Self { from: from.into(), to: to.into(), ..Default::default() }
    }
}

impl SectorStalkerParams {
    pub(crate) fn to_query(&self) -> Vec<(&'static str, String)> {
        let mut q = vec![("from", self.from.to_string()), ("to", self.to.to_string())];
        if let Some(v) = &self.base {
            q.push(("base", v.to_string()));
        }
        if let Some(v) = &self.limit {
            q.push(("limit", v.to_string()));
        }
        if let Some(v) = &self.filter {
            q.push(("filter", v.to_string()));
        }
        if let Some(v) = &self.filter_column {
            q.push(("filter_column", v.to_string()));
        }
        if let Some(v) = &self.filter_operator {
            q.push(("filter_operator", v.to_string()));
        }
        if let Some(v) = &self.filter_value {
            q.push(("filter_value", v.to_string()));
        }
        q
    }
}

